const crmMetrics = $node['Get CRM Metrics'].json;
const sourceBreakdown = $node['Get Source Breakdown'].json;
const activityMetrics = $node['Get Activity Metrics'].json;
const dealMetrics = $node['Get Deal Metrics'].json;

const crm = Array.isArray(crmMetrics) ? crmMetrics[0] : crmMetrics;
const sources = Array.isArray(sourceBreakdown) ? sourceBreakdown : [sourceBreakdown];
const activities = Array.isArray(activityMetrics) ? activityMetrics : [activityMetrics];
const deals = Array.isArray(dealMetrics) ? dealMetrics[0] : dealMetrics;

const month = new Date(Date.now() - 30*24*60*60*1000).toLocaleString('id-ID', { month: 'long', year: 'numeric' });

const report = {
  period: month,
  crm: {
    total_contacts: crm?.total_contacts || 0,
    new_contacts: crm?.new_contacts || 0,
    qualified_leads: crm?.qualified_leads || 0,
    customers: crm?.customers || 0,
    lost: crm?.lost || 0,
    avg_lead_score: crm?.avg_lead_score || 0,
    hot_leads: crm?.hot_leads || 0,
    conversion_rate: crm?.total_contacts > 0 
      ? Math.round((crm?.customers || 0) / crm.total_contacts * 100) 
      : 0
  },
  sources: sources.filter(s => s.source).map(s => ({
    source: s.source,
    count: s.count,
    avg_score: s.avg_score
  })),
  activities: activities.filter(a => a.activity_type).map(a => ({
    type: a.activity_type,
    count: a.count
  })),
  deals: {
    total: deals?.total_deals || 0,
    pipeline_value: deals?.total_pipeline_value || 0,
    won: deals?.won_deals || 0,
    won_value: deals?.won_value || 0,
    lost: deals?.lost_deals || 0,
    win_rate: deals?.win_rate || 0
  }
};

return [{ json: report }];

